                identity = id(value)
                if identity in active:
                    raise ValueError("Contract data must not contain recursive containers")
                active.add(identity)
                try:
                    if isinstance(value, dict):
                        for key, item in value.items():
                            check(key)
                            check(item)
                    else:
                        for item in value:
                            check(item)
                finally:
                    active.remove(identity)
        check(values)
        return values



