        def discard_turn(data):
            turn = data["turns"].get(turn_id)
            if not turn or turn.get("thread_id") != thread_id:
                raise DomainError(404, "Turn not found")
            if turn["state"] == "discarded":
                return turn
            if turn["state"] != "pending":
